-- Pyshio database schema for PostgreSQL 14+.
-- Generated by export_postgres.py from schema version 10. Tables: 57.
-- Dates/times are stored as ISO text (YYYY-MM-DDTHH:MM:SS, YYYY-MM-DD, HH:MM).
-- Money columns ending in _paise are integer paise (100 paise = 1 rupee); appointment fees are whole rupees.

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

CREATE TABLE "ai_calls" (
  "id" SERIAL,
  "capability" VARCHAR(255) NOT NULL,
  "user_id" INTEGER,
  "model" VARCHAR(255),
  "ok" BOOLEAN NOT NULL,
  "ms" INTEGER,
  "input_tokens" INTEGER,
  "output_tokens" INTEGER,
  "cache_read_tokens" INTEGER,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "ai_extractions" (
  "id" SERIAL,
  "kind" VARCHAR(24) NOT NULL CHECK (kind IN ('rx_upload', 'lab_report')),
  "source_id" VARCHAR(255) NOT NULL,
  "record_id" INTEGER,
  "status" VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'done', 'failed', 'skipped')),
  "engine" VARCHAR(255),
  "result" TEXT,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "claimed_at" VARCHAR(19),
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_ai_extractions_kind_source_id" UNIQUE ("kind", "source_id")
);

CREATE TABLE "app_secrets" (
  "key" VARCHAR(255) NOT NULL,
  "value" VARCHAR(255) NOT NULL,
  PRIMARY KEY ("key")
);

CREATE TABLE "appointments" (
  "id" VARCHAR(36) NOT NULL,
  "reference" VARCHAR(20) NOT NULL UNIQUE,
  "doctor_id" INTEGER NOT NULL,
  "patient_id" INTEGER NOT NULL,
  "service_id" INTEGER,
  "service_name" VARCHAR(255) NOT NULL,
  "duration" INTEGER NOT NULL,
  "fee" INTEGER NOT NULL,
  "appointment_date" VARCHAR(10) NOT NULL,
  "appointment_time" VARCHAR(5) NOT NULL,
  "status" VARCHAR(24) NOT NULL CHECK (status IN ('pending_payment', 'requested', 'awaiting_patient', 'confirmed', 'completed', 'no_show', 'cancelled', 'expired')),
  "reason" TEXT,
  "doctor_notes" TEXT,
  "payment_method" VARCHAR(10) NOT NULL CHECK (payment_method IN ('clinic', 'online')),
  "payment_status" VARCHAR(20) NOT NULL CHECK (payment_status IN ('unpaid', 'pending', 'paid', 'refunded', 'refund_failed', 'not_refundable')),
  "razorpay_order_id" VARCHAR(255),
  "razorpay_payment_id" VARCHAR(255),
  "refund_id" VARCHAR(255),
  "cancelled_by" VARCHAR(20),
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  "reminder_sent_at" VARCHAR(19),
  "visit_type" VARCHAR(10) NOT NULL DEFAULT 'clinic' CHECK (visit_type IN ('clinic', 'home', 'video')),
  "visit_address" TEXT,
  "visit_lat" DOUBLE PRECISION,
  "visit_lng" DOUBLE PRECISION,
  "travel_fee" INTEGER NOT NULL DEFAULT 0,
  "visit_note" TEXT,
  "quoted_at" VARCHAR(19),
  "family_member_id" INTEGER,
  "video_room" VARCHAR(255),
  "no_show_risk" INTEGER,
  "risk_nudged_at" VARCHAR(19),
  "attendance_confirmed_at" VARCHAR(19),
  PRIMARY KEY ("id")
);

CREATE TABLE "audit_log" (
  "id" SERIAL,
  "actor_id" INTEGER,
  "action" VARCHAR(255) NOT NULL,
  "target" VARCHAR(255),
  "detail" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "blocked_times" (
  "id" SERIAL,
  "doctor_id" INTEGER NOT NULL,
  "block_date" VARCHAR(10) NOT NULL,
  "start_time" VARCHAR(5),
  "end_time" VARCHAR(5),
  "reason" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "companies" (
  "id" SERIAL,
  "admin_id" INTEGER NOT NULL UNIQUE,
  "name" VARCHAR(255) NOT NULL,
  "cin" VARCHAR(255),
  "gstin" VARCHAR(255),
  "address" TEXT NOT NULL,
  "city" VARCHAR(60) NOT NULL,
  "state" VARCHAR(60),
  "website" VARCHAR(255),
  "status" VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'suspended')),
  "status_reason" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  "approved_at" VARCHAR(19),
  "updated_at" VARCHAR(19),
  PRIMARY KEY ("id")
);

CREATE TABLE "conditions" (
  "id" SERIAL,
  "code" VARCHAR(20) NOT NULL UNIQUE,
  "name" VARCHAR(255) NOT NULL,
  "care_area" VARCHAR(40) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "conversation_messages" (
  "id" SERIAL,
  "conversation_id" INTEGER NOT NULL,
  "author_role" VARCHAR(20) NOT NULL CHECK (author_role IN ('patient', 'pharmacy', 'lab', 'system')),
  "author_id" INTEGER,
  "body" TEXT NOT NULL,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "conversations" (
  "id" SERIAL,
  "patient_id" INTEGER NOT NULL,
  "partner_role" VARCHAR(10) NOT NULL CHECK (partner_role IN ('pharmacy', 'lab')),
  "partner_id" INTEGER NOT NULL,
  "subject_kind" VARCHAR(20) NOT NULL CHECK (subject_kind IN ('upload_order', 'medicine_order', 'lab_booking')),
  "subject_id" VARCHAR(36) NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "status" VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  "closed_by_role" VARCHAR(20),
  "created_at" VARCHAR(19) NOT NULL,
  "closed_at" VARCHAR(19),
  "last_message_at" VARCHAR(19) NOT NULL,
  "patient_read_at" VARCHAR(19),
  "partner_read_at" VARCHAR(19),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_conversations_subject_kind_subject_id" UNIQUE ("subject_kind", "subject_id")
);

CREATE TABLE "courses" (
  "id" SERIAL,
  "order_id" VARCHAR(36) NOT NULL,
  "prescription_id" VARCHAR(36) NOT NULL,
  "prescription_item_id" INTEGER NOT NULL,
  "patient_id" INTEGER NOT NULL,
  "pharmacy_id" INTEGER NOT NULL,
  "medicine_id" INTEGER,
  "name" VARCHAR(255) NOT NULL,
  "generic_name" VARCHAR(255),
  "strength" VARCHAR(40),
  "units" INTEGER NOT NULL,
  "daily_units" DOUBLE PRECISION,
  "is_long_term" BOOLEAN NOT NULL DEFAULT FALSE,
  "started_on" VARCHAR(10) NOT NULL,
  "ends_on" VARCHAR(10),
  "lat" DOUBLE PRECISION,
  "lng" DOUBLE PRECISION,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_courses_order_id_prescription_item_id" UNIQUE ("order_id", "prescription_item_id")
);

CREATE TABLE "divisions" (
  "id" SERIAL,
  "company_id" INTEGER NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "care_areas" VARCHAR(1000) NOT NULL DEFAULT '',
  "active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_divisions_company_id_name" UNIQUE ("company_id", "name")
);

CREATE TABLE "doctor_hours" (
  "id" SERIAL,
  "doctor_id" INTEGER NOT NULL,
  "weekday" INTEGER NOT NULL CHECK (weekday BETWEEN 0 AND 6),
  "start_time" VARCHAR(5) NOT NULL,
  "end_time" VARCHAR(5) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "doctors" (
  "user_id" INTEGER NOT NULL,
  "slug" VARCHAR(120) NOT NULL UNIQUE,
  "qualification" VARCHAR(255) NOT NULL,
  "registration_no" VARCHAR(255) NOT NULL,
  "registration_council" VARCHAR(255),
  "experience_years" INTEGER NOT NULL DEFAULT 0,
  "specialities" VARCHAR(1000) NOT NULL DEFAULT '',
  "bio" TEXT,
  "clinic_name" VARCHAR(255) NOT NULL,
  "address" TEXT NOT NULL,
  "city" VARCHAR(60) NOT NULL,
  "pincode" VARCHAR(6),
  "slot_minutes" INTEGER NOT NULL DEFAULT 30,
  "accepts_clinic_payment" BOOLEAN NOT NULL DEFAULT TRUE,
  "accepts_online_payment" BOOLEAN NOT NULL DEFAULT FALSE,
  "status" VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'suspended')),
  "status_reason" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  "approved_at" VARCHAR(19),
  "updated_at" VARCHAR(19),
  "category" VARCHAR(40) NOT NULL DEFAULT 'physiotherapist',
  "lat" DOUBLE PRECISION,
  "lng" DOUBLE PRECISION,
  "state" VARCHAR(60),
  "share_insights_at" VARCHAR(19),
  "accept_mr_meetings" BOOLEAN NOT NULL DEFAULT TRUE,
  "offers_home_visits" BOOLEAN NOT NULL DEFAULT FALSE,
  "home_visit_radius_km" DOUBLE PRECISION NOT NULL DEFAULT 5,
  "home_visit_fee" INTEGER,
  "offers_video" INTEGER NOT NULL DEFAULT 0,
  "video_fee" INTEGER,
  PRIMARY KEY ("user_id")
);

CREATE TABLE "dose_logs" (
  "id" SERIAL,
  "patient_id" INTEGER NOT NULL,
  "source" VARCHAR(20) NOT NULL CHECK (source IN ('course', 'rx', 'own')),
  "source_id" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "dose_date" VARCHAR(255) NOT NULL,
  "slot" VARCHAR(255) NOT NULL CHECK (slot IN ('morning', 'afternoon', 'evening', 'night')),
  "status" VARCHAR(24) NOT NULL CHECK (status IN ('taken', 'skipped')),
  "logged_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_dose_logs_patient_id_source_source_id_dose_date_slot" UNIQUE ("patient_id", "source", "source_id", "dose_date", "slot")
);

CREATE TABLE "family_members" (
  "id" SERIAL,
  "patient_id" INTEGER NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "relation" VARCHAR(255) NOT NULL,
  "dob" VARCHAR(10),
  "sex" VARCHAR(10),
  "blood_group" VARCHAR(255),
  "allergies" VARCHAR(255),
  "conditions" VARCHAR(255),
  "created_at" VARCHAR(19) NOT NULL,
  "deleted_at" VARCHAR(19),
  PRIMARY KEY ("id")
);

CREATE TABLE "health_records" (
  "id" SERIAL,
  "patient_id" INTEGER NOT NULL,
  "kind" VARCHAR(24) NOT NULL CHECK (kind IN ('lab_report', 'other_report', 'prescription_copy', 'medicine_bill', 'other')),
  "title" VARCHAR(255) NOT NULL,
  "record_date" VARCHAR(10) NOT NULL,
  "file_path" VARCHAR(255),
  "file_name" VARCHAR(255),
  "content_type" VARCHAR(60),
  "size_bytes" INTEGER,
  "uploaded_by" INTEGER,
  "uploader_role" VARCHAR(20) NOT NULL,
  "lab_booking_id" VARCHAR(36),
  "lab_id" INTEGER,
  "doctor_id" INTEGER,
  "share_with_doctors" BOOLEAN NOT NULL DEFAULT TRUE,
  "notes" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  "deleted_at" VARCHAR(19),
  "upload_order_id" VARCHAR(36),
  "family_member_id" INTEGER,
  PRIMARY KEY ("id")
);

CREATE TABLE "intel_alerts" (
  "id" SERIAL,
  "kind" VARCHAR(24) NOT NULL,
  "subject_id" VARCHAR(36) NOT NULL,
  "period" VARCHAR(255) NOT NULL,
  "payload" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_intel_alerts_kind_subject_id_period" UNIQUE ("kind", "subject_id", "period")
);

CREATE TABLE "lab_booking_items" (
  "id" SERIAL,
  "booking_id" VARCHAR(36) NOT NULL,
  "prescription_test_id" INTEGER NOT NULL,
  "test_id" INTEGER,
  "name" VARCHAR(255) NOT NULL,
  "price_paise" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "lab_bookings" (
  "id" VARCHAR(36) NOT NULL,
  "reference" VARCHAR(20) NOT NULL UNIQUE,
  "prescription_id" VARCHAR(36) NOT NULL,
  "lab_id" INTEGER NOT NULL,
  "patient_id" INTEGER NOT NULL,
  "quote_id" INTEGER,
  "collection" VARCHAR(10) NOT NULL CHECK (collection IN ('visit', 'home')),
  "preferred_date" VARCHAR(10),
  "preferred_time" VARCHAR(5),
  "address" TEXT,
  "distance_km" DOUBLE PRECISION,
  "subtotal_paise" BIGINT NOT NULL,
  "collection_fee_paise" BIGINT NOT NULL DEFAULT 0,
  "total_paise" BIGINT NOT NULL,
  "payment_method" VARCHAR(10) NOT NULL DEFAULT 'lab' CHECK (payment_method IN ('lab')),
  "payment_status" VARCHAR(20) NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid', 'paid')),
  "status" VARCHAR(24) NOT NULL CHECK (status IN ('booked', 'accepted', 'sample_collected', 'report_ready', 'completed', 'rejected', 'cancelled')),
  "status_reason" TEXT,
  "reminded_at" VARCHAR(19),
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "lab_prices" (
  "lab_id" INTEGER NOT NULL,
  "test_id" INTEGER NOT NULL,
  "mrp_paise" BIGINT NOT NULL,
  "price_paise" BIGINT NOT NULL,
  "available" BOOLEAN NOT NULL DEFAULT TRUE,
  "report_hours" INTEGER,
  "updated_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("lab_id", "test_id")
);

CREATE TABLE "lab_quote_items" (
  "quote_id" INTEGER NOT NULL,
  "prescription_test_id" INTEGER NOT NULL,
  "available" BOOLEAN NOT NULL,
  "price_paise" BIGINT NOT NULL DEFAULT 0,
  "mrp_paise" BIGINT
);

CREATE TABLE "lab_quotes" (
  "id" SERIAL,
  "prescription_id" VARCHAR(36) NOT NULL,
  "lab_id" INTEGER NOT NULL,
  "subtotal_paise" BIGINT NOT NULL,
  "home_collection" BOOLEAN NOT NULL DEFAULT FALSE,
  "collection_fee_paise" BIGINT NOT NULL DEFAULT 0,
  "report_hours" INTEGER,
  "note" TEXT,
  "status" VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'withdrawn', 'accepted', 'lost')),
  "created_at" VARCHAR(19) NOT NULL,
  "valid_until" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "lab_requests" (
  "id" SERIAL,
  "prescription_id" VARCHAR(36) NOT NULL,
  "lab_id" INTEGER NOT NULL,
  "distance_km" DOUBLE PRECISION NOT NULL,
  "status" VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'quoted', 'declined', 'closed')),
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  "outcome" VARCHAR(20),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_lab_requests_prescription_id_lab_id" UNIQUE ("prescription_id", "lab_id")
);

CREATE TABLE "lab_tests" (
  "id" SERIAL,
  "name" VARCHAR(255) NOT NULL,
  "code" VARCHAR(20),
  "category" VARCHAR(40) NOT NULL DEFAULT 'Blood',
  "sample_type" VARCHAR(255),
  "fasting" BOOLEAN NOT NULL DEFAULT FALSE,
  "mrp_paise" BIGINT,
  "unit" VARCHAR(20),
  "ref_low" DOUBLE PRECISION,
  "ref_high" DOUBLE PRECISION,
  "created_by" INTEGER,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "labs" (
  "user_id" INTEGER NOT NULL,
  "slug" VARCHAR(120) NOT NULL UNIQUE,
  "lab_name" VARCHAR(255) NOT NULL,
  "registration_no" VARCHAR(255) NOT NULL,
  "nabl_no" VARCHAR(255),
  "pathologist_name" VARCHAR(255) NOT NULL,
  "pathologist_reg_no" VARCHAR(255) NOT NULL,
  "gstin" VARCHAR(255),
  "address" TEXT NOT NULL,
  "city" VARCHAR(60) NOT NULL,
  "state" VARCHAR(60),
  "pincode" VARCHAR(6),
  "lat" DOUBLE PRECISION NOT NULL,
  "lng" DOUBLE PRECISION NOT NULL,
  "opening_hours" VARCHAR(255),
  "home_collection" BOOLEAN NOT NULL DEFAULT FALSE,
  "collection_fee_paise" BIGINT NOT NULL DEFAULT 0,
  "collection_radius_km" DOUBLE PRECISION NOT NULL DEFAULT 3,
  "flat_discount_percent" DOUBLE PRECISION,
  "report_hours" INTEGER NOT NULL DEFAULT 24,
  "status" VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'suspended')),
  "status_reason" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  "approved_at" VARCHAR(19),
  "updated_at" VARCHAR(19),
  PRIMARY KEY ("user_id")
);

CREATE TABLE "login_failures" (
  "email" VARCHAR(254) NOT NULL,
  "failed_at" VARCHAR(19) NOT NULL
);

CREATE TABLE "medicine_orders" (
  "id" VARCHAR(36) NOT NULL,
  "reference" VARCHAR(20) NOT NULL UNIQUE,
  "prescription_id" VARCHAR(36) NOT NULL,
  "pharmacy_id" INTEGER NOT NULL,
  "patient_id" INTEGER NOT NULL,
  "quote_id" INTEGER,
  "source" VARCHAR(20) NOT NULL CHECK (source IN ('quote', 'price_list')),
  "subtotal_paise" BIGINT NOT NULL,
  "delivery_fee_paise" BIGINT NOT NULL DEFAULT 0,
  "total_paise" BIGINT NOT NULL,
  "fulfilment" VARCHAR(10) NOT NULL CHECK (fulfilment IN ('pickup', 'delivery')),
  "delivery_address" TEXT,
  "distance_km" DOUBLE PRECISION,
  "payment_method" VARCHAR(10) NOT NULL CHECK (payment_method IN ('pharmacy', 'online')),
  "payment_status" VARCHAR(20) NOT NULL CHECK (payment_status IN ('unpaid', 'pending', 'paid', 'refunded', 'refund_failed')),
  "razorpay_order_id" VARCHAR(255),
  "razorpay_payment_id" VARCHAR(255),
  "refund_id" VARCHAR(255),
  "status" VARCHAR(24) NOT NULL CHECK (status IN ('pending_payment', 'placed', 'accepted', 'ready', 'out_for_delivery', 'completed', 'rejected', 'cancelled', 'expired')),
  "status_reason" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  "delivery_otp" VARCHAR(255),
  "reminded_at" VARCHAR(19),
  PRIMARY KEY ("id")
);

CREATE TABLE "medicines" (
  "id" SERIAL,
  "name" VARCHAR(255) NOT NULL,
  "generic_name" VARCHAR(255),
  "strength" VARCHAR(40),
  "form" VARCHAR(20),
  "pack_size" INTEGER NOT NULL DEFAULT 1,
  "rx_required" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_by" INTEGER,
  "created_at" VARCHAR(19) NOT NULL,
  "mrp_paise" BIGINT,
  "care_area" VARCHAR(40),
  "manufacturer" VARCHAR(255),
  "company_id" INTEGER,
  "salt_key" VARCHAR(255),
  "strength_key" VARCHAR(255),
  PRIMARY KEY ("id")
);

CREATE TABLE "messages" (
  "id" SERIAL,
  "appointment_id" VARCHAR(36) NOT NULL,
  "author_id" INTEGER NOT NULL,
  "author_role" VARCHAR(20) NOT NULL,
  "body" TEXT NOT NULL,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "mr_requests" (
  "id" SERIAL,
  "mr_id" INTEGER NOT NULL,
  "doctor_id" INTEGER NOT NULL,
  "company_id" INTEGER NOT NULL,
  "division_id" INTEGER,
  "purpose" TEXT NOT NULL,
  "products" TEXT,
  "preferred_date" VARCHAR(10),
  "preferred_time" VARCHAR(5),
  "status" VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'declined', 'completed', 'cancelled')),
  "doctor_note" TEXT,
  "scheduled_for" VARCHAR(19),
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "mrs" (
  "user_id" INTEGER NOT NULL,
  "company_id" INTEGER NOT NULL,
  "division_id" INTEGER,
  "employee_code" VARCHAR(255),
  "territory_city" VARCHAR(255),
  "territory_state" VARCHAR(255),
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("user_id")
);

CREATE TABLE "notifications" (
  "id" SERIAL,
  "user_id" INTEGER NOT NULL,
  "kind" VARCHAR(24) NOT NULL DEFAULT 'update',
  "title" VARCHAR(255) NOT NULL,
  "body" TEXT,
  "link" VARCHAR(255),
  "created_at" VARCHAR(19) NOT NULL,
  "read_at" VARCHAR(19),
  PRIMARY KEY ("id")
);

CREATE TABLE "order_items" (
  "id" SERIAL,
  "order_id" VARCHAR(36) NOT NULL,
  "prescription_item_id" INTEGER NOT NULL,
  "medicine_id" INTEGER,
  "name" VARCHAR(255) NOT NULL,
  "quantity" INTEGER NOT NULL,
  "unit_price_paise" BIGINT NOT NULL,
  "line_paise" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "password_resets" (
  "token_hash" VARCHAR(64) NOT NULL,
  "user_id" INTEGER NOT NULL,
  "expires_at" VARCHAR(19) NOT NULL,
  "used_at" VARCHAR(19),
  PRIMARY KEY ("token_hash")
);

CREATE TABLE "patient_medicines" (
  "id" SERIAL,
  "patient_id" INTEGER NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "strength" VARCHAR(40),
  "dosage" VARCHAR(255),
  "since" VARCHAR(10),
  "prescribed_by" VARCHAR(255),
  "notes" TEXT,
  "active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  "generic_name" VARCHAR(255),
  "medicine_id" INTEGER,
  PRIMARY KEY ("id")
);

CREATE TABLE "payouts" (
  "id" SERIAL,
  "payee_role" VARCHAR(255) NOT NULL CHECK (payee_role IN ('doctor', 'pharmacy')),
  "payee_id" INTEGER NOT NULL,
  "amount_paise" BIGINT NOT NULL,
  "reference" VARCHAR(20),
  "note" TEXT,
  "created_by" INTEGER,
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "pharmacies" (
  "user_id" INTEGER NOT NULL,
  "slug" VARCHAR(120) NOT NULL UNIQUE,
  "store_name" VARCHAR(255) NOT NULL,
  "drug_licence_no" VARCHAR(255) NOT NULL,
  "pharmacist_name" VARCHAR(255) NOT NULL,
  "pharmacist_reg_no" VARCHAR(255) NOT NULL,
  "gstin" VARCHAR(255),
  "address" TEXT NOT NULL,
  "city" VARCHAR(60) NOT NULL,
  "pincode" VARCHAR(6),
  "lat" DOUBLE PRECISION NOT NULL,
  "lng" DOUBLE PRECISION NOT NULL,
  "opening_hours" VARCHAR(255),
  "offers_delivery" BOOLEAN NOT NULL DEFAULT FALSE,
  "delivery_radius_km" DOUBLE PRECISION NOT NULL DEFAULT 3,
  "delivery_fee_paise" BIGINT NOT NULL DEFAULT 0,
  "accepts_online_payment" BOOLEAN NOT NULL DEFAULT FALSE,
  "status" VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'suspended')),
  "status_reason" TEXT,
  "created_at" VARCHAR(19) NOT NULL,
  "approved_at" VARCHAR(19),
  "updated_at" VARCHAR(19),
  "flat_discount_percent" DOUBLE PRECISION,
  "pickup_ready_minutes" INTEGER NOT NULL DEFAULT 15,
  "delivery_minutes" INTEGER NOT NULL DEFAULT 60,
  "state" VARCHAR(60),
  PRIMARY KEY ("user_id")
);

CREATE TABLE "pharmacy_stock" (
  "pharmacy_id" INTEGER NOT NULL,
  "medicine_id" INTEGER NOT NULL,
  "mrp_paise" BIGINT NOT NULL,
  "price_paise" BIGINT NOT NULL,
  "in_stock" BOOLEAN NOT NULL DEFAULT TRUE,
  "updated_at" VARCHAR(19) NOT NULL,
  "on_hand" INTEGER,
  PRIMARY KEY ("pharmacy_id", "medicine_id")
);

CREATE TABLE "prescription_conditions" (
  "prescription_id" VARCHAR(36) NOT NULL,
  "condition_id" INTEGER NOT NULL,
  PRIMARY KEY ("prescription_id", "condition_id")
);

CREATE TABLE "prescription_items" (
  "id" SERIAL,
  "prescription_id" VARCHAR(36) NOT NULL,
  "medicine_id" INTEGER,
  "name" VARCHAR(255) NOT NULL,
  "generic_name" VARCHAR(255),
  "strength" VARCHAR(40),
  "form" VARCHAR(20),
  "dosage" VARCHAR(255),
  "duration" VARCHAR(255),
  "quantity" INTEGER NOT NULL,
  "instructions" TEXT,
  "allow_substitute" BOOLEAN NOT NULL DEFAULT TRUE,
  "daily_units" DOUBLE PRECISION,
  "duration_days" INTEGER,
  "is_long_term" BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY ("id")
);

CREATE TABLE "prescription_tests" (
  "id" SERIAL,
  "prescription_id" VARCHAR(36) NOT NULL,
  "test_id" INTEGER,
  "name" VARCHAR(255) NOT NULL,
  "instructions" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE "prescriptions" (
  "id" VARCHAR(36) NOT NULL,
  "reference" VARCHAR(20) NOT NULL UNIQUE,
  "appointment_id" VARCHAR(36),
  "doctor_id" INTEGER NOT NULL,
  "patient_id" INTEGER NOT NULL,
  "patient_age" INTEGER,
  "patient_sex" VARCHAR(255),
  "diagnosis" TEXT,
  "advice" TEXT,
  "lat" DOUBLE PRECISION,
  "lng" DOUBLE PRECISION,
  "location_source" VARCHAR(20),
  "radius_km" DOUBLE PRECISION NOT NULL,
  "status" VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'cancelled')),
  "created_at" VARCHAR(19) NOT NULL,
  "valid_until" VARCHAR(19) NOT NULL,
  "expiry_reminded_at" VARCHAR(19),
  "parent_id" VARCHAR(36),
  "refill_number" INTEGER NOT NULL DEFAULT 0,
  "refills_allowed" INTEGER NOT NULL DEFAULT 0,
  "refills_used" INTEGER NOT NULL DEFAULT 0,
  "refill_until" VARCHAR(19),
  "refill_reminded_at" VARCHAR(19),
  "family_member_id" INTEGER,
  "follow_up_on" VARCHAR(255),
  "follow_up_reminded_at" VARCHAR(19),
  "pregnancy" VARCHAR(255),
  "safety_alerts" TEXT,
  "safety_ack_at" VARCHAR(19),
  PRIMARY KEY ("id")
);

CREATE TABLE "quote_items" (
  "quote_id" INTEGER NOT NULL,
  "prescription_item_id" INTEGER NOT NULL,
  "available" BOOLEAN NOT NULL,
  "supplied_name" VARCHAR(255),
  "unit_price_paise" BIGINT NOT NULL DEFAULT 0,
  "quantity" INTEGER NOT NULL,
  "line_paise" BIGINT NOT NULL DEFAULT 0,
  "mrp_paise" BIGINT
);

CREATE TABLE "quotes" (
  "id" SERIAL,
  "prescription_id" VARCHAR(36) NOT NULL,
  "pharmacy_id" INTEGER NOT NULL,
  "subtotal_paise" BIGINT NOT NULL,
  "delivery_available" BOOLEAN NOT NULL DEFAULT FALSE,
  "delivery_fee_paise" BIGINT NOT NULL DEFAULT 0,
  "ready_in_minutes" INTEGER,
  "note" TEXT,
  "status" VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'withdrawn', 'accepted', 'lost')),
  "created_at" VARCHAR(19) NOT NULL,
  "valid_until" VARCHAR(19) NOT NULL,
  "delivery_minutes" INTEGER,
  PRIMARY KEY ("id")
);

CREATE TABLE "rate_limits" (
  "key" VARCHAR(255) NOT NULL,
  "hit_at" VARCHAR(19) NOT NULL
);

CREATE TABLE "record_values" (
  "id" SERIAL,
  "record_id" INTEGER NOT NULL,
  "test_id" INTEGER,
  "name" VARCHAR(255) NOT NULL,
  "value_num" DOUBLE PRECISION,
  "value_text" TEXT,
  "unit" VARCHAR(20),
  "ref_low" DOUBLE PRECISION,
  "ref_high" DOUBLE PRECISION,
  "flag" VARCHAR(10) CHECK (flag IN ('low', 'normal', 'high')),
  PRIMARY KEY ("id")
);

CREATE TABLE "reviews" (
  "id" SERIAL,
  "patient_id" INTEGER NOT NULL,
  "target_role" VARCHAR(20) NOT NULL CHECK (target_role IN ('doctor', 'pharmacy')),
  "target_id" INTEGER NOT NULL,
  "appointment_id" VARCHAR(36) UNIQUE,
  "order_id" VARCHAR(36) UNIQUE,
  "rating" INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  "comment" VARCHAR(255),
  "created_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "rx_requests" (
  "id" SERIAL,
  "prescription_id" VARCHAR(36) NOT NULL,
  "pharmacy_id" INTEGER NOT NULL,
  "distance_km" DOUBLE PRECISION NOT NULL,
  "status" VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'quoted', 'declined', 'closed')),
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  "outcome" VARCHAR(20),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_rx_requests_prescription_id_pharmacy_id" UNIQUE ("prescription_id", "pharmacy_id")
);

CREATE TABLE "rx_uploads" (
  "id" VARCHAR(36) NOT NULL,
  "reference" VARCHAR(20) NOT NULL UNIQUE,
  "patient_id" INTEGER NOT NULL,
  "record_id" INTEGER NOT NULL,
  "want_medicines" BOOLEAN NOT NULL DEFAULT TRUE,
  "want_tests" BOOLEAN NOT NULL DEFAULT FALSE,
  "note" TEXT,
  "lat" DOUBLE PRECISION NOT NULL,
  "lng" DOUBLE PRECISION NOT NULL,
  "radius_km" DOUBLE PRECISION NOT NULL,
  "status" VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed', 'cancelled')),
  "created_at" VARCHAR(19) NOT NULL,
  "valid_until" VARCHAR(19) NOT NULL,
  "ai_read_consent" BOOLEAN NOT NULL DEFAULT FALSE,
  "typed_lines" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE "services" (
  "id" SERIAL,
  "doctor_id" INTEGER NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "duration" INTEGER NOT NULL,
  "fee" INTEGER NOT NULL,
  "active" BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY ("id")
);

CREATE TABLE "sessions" (
  "token_hash" VARCHAR(64) NOT NULL,
  "user_id" INTEGER NOT NULL,
  "created_at" VARCHAR(19) NOT NULL,
  "expires_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("token_hash")
);

CREATE TABLE "upload_orders" (
  "id" VARCHAR(36) NOT NULL,
  "reference" VARCHAR(20) NOT NULL UNIQUE,
  "upload_id" VARCHAR(36) NOT NULL,
  "quote_id" INTEGER NOT NULL,
  "patient_id" INTEGER NOT NULL,
  "partner_role" VARCHAR(10) NOT NULL CHECK (partner_role IN ('pharmacy', 'lab')),
  "partner_id" INTEGER NOT NULL,
  "fulfilment" VARCHAR(10) NOT NULL CHECK (fulfilment IN ('pickup', 'delivery', 'visit', 'home')),
  "address" TEXT,
  "preferred_date" VARCHAR(10),
  "preferred_time" VARCHAR(5),
  "subtotal_paise" BIGINT NOT NULL,
  "fee_paise" BIGINT NOT NULL DEFAULT 0,
  "total_paise" BIGINT NOT NULL,
  "payment_status" VARCHAR(20) NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid', 'paid')),
  "status" VARCHAR(24) NOT NULL CHECK (status IN ('placed', 'accepted', 'ready', 'sample_collected', 'report_ready', 'completed', 'rejected', 'cancelled')),
  "status_reason" TEXT,
  "handover_code" VARCHAR(255),
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "upload_quote_lines" (
  "id" SERIAL,
  "quote_id" INTEGER NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "quantity" INTEGER NOT NULL,
  "available" BOOLEAN NOT NULL DEFAULT TRUE,
  "unit_price_paise" BIGINT NOT NULL DEFAULT 0,
  "mrp_paise" BIGINT,
  "medicine_id" INTEGER,
  PRIMARY KEY ("id")
);

CREATE TABLE "upload_quotes" (
  "id" SERIAL,
  "upload_id" VARCHAR(36) NOT NULL,
  "partner_role" VARCHAR(10) NOT NULL CHECK (partner_role IN ('pharmacy', 'lab')),
  "partner_id" INTEGER NOT NULL,
  "subtotal_paise" BIGINT NOT NULL,
  "mrp_total_paise" BIGINT NOT NULL,
  "lines_total" INTEGER NOT NULL,
  "lines_available" INTEGER NOT NULL,
  "delivery_available" BOOLEAN NOT NULL DEFAULT FALSE,
  "delivery_fee_paise" BIGINT NOT NULL DEFAULT 0,
  "ready_minutes" INTEGER,
  "delivery_minutes" INTEGER,
  "note" TEXT,
  "status" VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'withdrawn', 'accepted', 'lost')),
  "created_at" VARCHAR(19) NOT NULL,
  "valid_until" VARCHAR(19) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "upload_requests" (
  "id" SERIAL,
  "upload_id" VARCHAR(36) NOT NULL,
  "partner_role" VARCHAR(10) NOT NULL CHECK (partner_role IN ('pharmacy', 'lab')),
  "partner_id" INTEGER NOT NULL,
  "distance_km" DOUBLE PRECISION NOT NULL,
  "status" VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'quoted', 'declined', 'closed')),
  "created_at" VARCHAR(19) NOT NULL,
  "updated_at" VARCHAR(19) NOT NULL,
  "outcome" VARCHAR(20),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_upload_requests_upload_id_partner_id" UNIQUE ("upload_id", "partner_id")
);

CREATE TABLE "users" (
  "id" SERIAL,
  "role" VARCHAR(20) NOT NULL CHECK (role IN ('patient', 'doctor', 'admin', 'pharmacy', 'company', 'mr', 'lab')),
  "name" VARCHAR(255) NOT NULL,
  "email" VARCHAR(254) NOT NULL UNIQUE,
  "phone" VARCHAR(20),
  "password_hash" VARCHAR(255) NOT NULL,
  "is_active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" VARCHAR(19) NOT NULL,
  "last_login_at" VARCHAR(19),
  "home_address" TEXT,
  "home_lat" DOUBLE PRECISION,
  "home_lng" DOUBLE PRECISION,
  "share_consent_at" VARCHAR(19),
  "dob" VARCHAR(10),
  "sex" VARCHAR(10),
  "deleted_at" VARCHAR(19),
  "city" VARCHAR(60),
  "state" VARCHAR(60),
  "blood_group" VARCHAR(255),
  "allergies" VARCHAR(255),
  "chronic_conditions" VARCHAR(255),
  "emergency_name" VARCHAR(255),
  "emergency_phone" VARCHAR(255),
  "remind_times" VARCHAR(255),
  "dose_email_digest" INTEGER NOT NULL DEFAULT 0,
  "dose_digest_on" VARCHAR(255),
  PRIMARY KEY ("id")
);

